-- Original refund-return balance evidence only. No balance or credit changes.
CREATE TABLE public.checkout_refund_return_inspections(
 academy_id uuid NOT NULL,id uuid NOT NULL,start_id uuid NOT NULL,refund_inspection_id uuid NOT NULL,refund_id text NOT NULL,worker_id uuid NOT NULL,request_sha256 text NOT NULL CHECK(request_sha256~'^[a-f0-9]{64}$'),
 return_inspection jsonb NOT NULL CHECK(jsonb_typeof(return_inspection)='object' AND octet_length(return_inspection::text)<=65536),object_conflict boolean NOT NULL,origin_transaction xid8 NOT NULL DEFAULT pg_current_xact_id(),recorded_by name NOT NULL DEFAULT session_user,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),FOREIGN KEY(academy_id,start_id) REFERENCES public.payment_checkout_dispatch_starts(academy_id,id),FOREIGN KEY(academy_id,refund_inspection_id) REFERENCES public.checkout_refund_inspections(academy_id,id)
);
CREATE INDEX checkout_refund_return_history ON public.checkout_refund_return_inspections(academy_id,start_id,refund_id,received_at DESC,id DESC);
CREATE TABLE public.checkout_refund_return_bindings(
 academy_id uuid NOT NULL,account_id text NOT NULL,livemode boolean NOT NULL,transaction_id text NOT NULL,start_id uuid NOT NULL,refund_id text NOT NULL,amount numeric NOT NULL,currency text NOT NULL,
 PRIMARY KEY(academy_id,account_id,livemode,transaction_id),FOREIGN KEY(academy_id,start_id) REFERENCES public.payment_checkout_dispatch_starts(academy_id,id)
);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['checkout_refund_return_inspections','checkout_refund_return_bindings'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);
 EXECUTE format('CREATE POLICY checkout_result_executor ON public.%I TO kavosh_checkout_result_policy USING(true) WITH CHECK(true)',t);
 EXECUTE format('GRANT SELECT,INSERT ON public.%I TO kavosh_checkout_result_policy',t);EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);
END LOOP;END $$;
GRANT CREATE ON SCHEMA public TO kavosh_checkout_result_policy;
CREATE FUNCTION public.record_checkout_refund_return_inspection(p_academy uuid,p_id uuid,p_start uuid,p_page uuid,p_worker uuid,p_hash text,p_return jsonb) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE original record;existing record;draft jsonb;j jsonb:=p_return;r jsonb;keys text[];field text;d jsonb;total numeric:=0;complete boolean:=true;fx boolean;matched boolean;binding text;recognized boolean;manual boolean;conflict boolean;scale integer;BEGIN
 IF p_academy IS NULL OR p_id IS NULL OR p_start IS NULL OR p_page IS NULL OR p_worker IS NULL OR p_hash IS NULL OR p_hash!~'^[a-f0-9]{64}$' OR j IS NULL OR jsonb_typeof(j)<>'object' OR octet_length(j::text)>65536 THEN RAISE EXCEPTION 'INVALID_REFUND_RETURN_INSPECTION' USING ERRCODE='23514';END IF;
 SELECT * INTO original FROM public.checkout_refund_inspections WHERE academy_id=p_academy AND id=p_page AND start_id=p_start AND request_sha256=p_hash;
 SELECT a.draft INTO draft FROM public.payment_checkout_dispatch_starts s JOIN public.payment_checkout_attempts a ON a.academy_id=s.academy_id AND a.id=s.attempt_id WHERE s.academy_id=p_academy AND s.id=p_start AND a.request_sha256=p_hash;
 IF original.id IS NULL OR draft IS NULL THEN RETURN 'unavailable';END IF;
 SELECT value INTO r FROM jsonb_array_elements(original.refund_inspection->'refunds') WHERE value->>'id'=j->>'refundId';
 IF r IS NULL OR original.refund_inspection->>'state'<>'refund_page' OR j->'sessionId' IS DISTINCT FROM original.refund_inspection->'sessionId' OR j->'paymentId' IS DISTINCT FROM original.refund_inspection->'paymentId' OR j->'chargeId' IS DISTINCT FROM original.refund_inspection->'chargeId' OR j->'refundStatus' IS DISTINCT FROM r->'status' OR j->'refundAmount' IS DISTINCT FROM r->'amount' OR j->'refundCurrency' IS DISTINCT FROM r->'currency' OR j->'refundCreatedAt' IS DISTINCT FROM r->'createdAt' OR j->'originalBalanceTransactionId' IS DISTINCT FROM r->'balanceTransactionId' OR j->'failureBalanceTransactionId' IS DISTINCT FROM r->'failureBalanceTransactionId' THEN RAISE EXCEPTION 'REFUND_RETURN_ORIGINAL_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 FOREACH field IN ARRAY ARRAY['bankSettled','ledgerAdjusted','creditRestored'] LOOP IF j->field IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'REFUND_RETURN_NOT_ACCOUNTING_AUTHORITY' USING ERRCODE='23514';END IF;END LOOP;
 keys=ARRAY['state','sessionId','paymentId','chargeId','refundId','refundStatus','refundAmount','refundCurrency','refundCreatedAt','originalBalanceTransactionId','failureBalanceTransactionId','bankSettled','ledgerAdjusted','creditRestored'];
 IF j->>'state'='return_balance' THEN
  keys=keys||ARRAY['balanceTransactionId','balanceType','transactionType','reportingCategory','source','providerUnitScale','grossAmount','currency','feeAmount','netAmount','createdAt','availableOn','status','exchangeRate','feeDetails','feeBreakdownComplete','requiresFxReview','principalAmountMatched','sourceBinding','recognizedType','requiresManualReview'];
  IF r->>'status' IS NULL OR r->>'status' NOT IN('failed','canceled') OR r->'failureBalanceTransactionId'='null'::jsonb OR r->'failureBalanceTransactionId'=r->'balanceTransactionId' OR j->'balanceTransactionId' IS DISTINCT FROM r->'failureBalanceTransactionId' THEN RAISE EXCEPTION 'REFUND_RETURN_POINTER_REQUIRED' USING ERRCODE='23514';END IF;
  FOREACH field IN ARRAY ARRAY['grossAmount','feeAmount','netAmount'] LOOP IF jsonb_typeof(j->field) IS DISTINCT FROM 'number' OR(j->>field)!~'^-?(0|[1-9][0-9]{0,11})$' THEN RAISE EXCEPTION 'REFUND_RETURN_MONEY_INVALID' USING ERRCODE='23514';END IF;END LOOP;
  IF(j->>'netAmount')::numeric<>(j->>'grossAmount')::numeric-(j->>'feeAmount')::numeric OR j->>'currency' IS NULL OR(j->>'currency')!~'^[a-z]{3}$' OR j->>'transactionType' IS NULL OR(j->>'transactionType')!~'^[a-z][a-z0-9_]{0,63}$' OR j->>'reportingCategory' IS NULL OR(j->>'reportingCategory')!~'^[a-z][a-z0-9_]{0,63}$' OR j->>'status' IS NULL OR j->>'status' NOT IN('pending','available') THEN RAISE EXCEPTION 'REFUND_RETURN_MONEY_INVALID' USING ERRCODE='23514';END IF;
  FOREACH field IN ARRAY ARRAY['createdAt','availableOn'] LOOP IF jsonb_typeof(j->field) IS DISTINCT FROM 'number' OR(j->>field)!~'^[1-9][0-9]{0,9}$' OR(j->>field)::numeric>9999999999 THEN RAISE EXCEPTION 'REFUND_RETURN_DATE_INVALID' USING ERRCODE='23514';END IF;END LOOP;
  IF NOT j?'source' OR jsonb_typeof(j->'source') NOT IN('string','null') OR(j->'source'<>'null'::jsonb AND(j->>'source')!~'^[A-Za-z][A-Za-z0-9_]{1,220}$') OR NOT j?'balanceType' OR jsonb_typeof(j->'balanceType') NOT IN('string','null') OR(j->'balanceType'<>'null'::jsonb AND(j->>'balanceType')!~'^[a-z][a-z0-9_]{0,63}$') OR NOT j?'exchangeRate' OR jsonb_typeof(j->'exchangeRate') NOT IN('number','null') OR(j->'exchangeRate'<>'null'::jsonb AND(length(j->>'exchangeRate')>40 OR(j->>'exchangeRate')::numeric<=0)) THEN RAISE EXCEPTION 'REFUND_RETURN_BALANCE_INVALID' USING ERRCODE='23514';END IF;
  scale=CASE public.checkout_provider_amount(upper(j->>'currency'),0,1) WHEN 1 THEN 0 WHEN 100 THEN 2 WHEN 1000 THEN 3 ELSE -1 END;IF j->'providerUnitScale' IS DISTINCT FROM to_jsonb(scale) THEN RAISE EXCEPTION 'REFUND_RETURN_SCALE_INVALID' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(j->'feeDetails') IS DISTINCT FROM 'array' OR jsonb_array_length(j->'feeDetails')>100 THEN RAISE EXCEPTION 'REFUND_RETURN_FEES_INVALID' USING ERRCODE='23514';END IF;
  FOR d IN SELECT value FROM jsonb_array_elements(j->'feeDetails') LOOP
   IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR d-ARRAY['amount','currency','type','application']<>'{}'::jsonb OR NOT(d?&ARRAY['amount','currency','type']) OR jsonb_typeof(d->'amount') IS DISTINCT FROM 'number' OR(d->>'amount')!~'^-?(0|[1-9][0-9]{0,11})$' OR d->>'currency' IS NULL OR(d->>'currency')!~'^[a-z]{3}$' OR d->>'type' IS NULL OR(d->>'type')!~'^[a-z][a-z0-9_]{0,63}$' OR(d?'application' AND(jsonb_typeof(d->'application') NOT IN('string','null') OR(d->'application'<>'null'::jsonb AND(d->>'application')!~'^[A-Za-z0-9_]{1,200}$'))) THEN RAISE EXCEPTION 'REFUND_RETURN_FEES_INVALID' USING ERRCODE='23514';END IF;
   total=total+(d->>'amount')::numeric;complete=complete AND d->>'currency'=j->>'currency';
  END LOOP;complete=complete AND total=(j->>'feeAmount')::numeric;fx=j->>'currency'<>r->>'currency';matched=NOT fx AND(j->>'grossAmount')::numeric=(r->>'amount')::numeric;
  binding=CASE WHEN j->>'source'=r->>'id' THEN 'refund' WHEN j->>'source'=original.refund_inspection->>'chargeId' THEN 'charge' WHEN j->'source'='null'::jsonb THEN 'pointer' ELSE 'mismatch' END;recognized=j->>'transactionType' IN('refund_failure','payment_refund','adjustment');manual=fx OR NOT matched OR binding='mismatch' OR NOT recognized OR NOT complete OR(j->>'feeAmount')::numeric<>0 OR(j->>'grossAmount')::numeric<=0 OR j->'balanceType' IS DISTINCT FROM '"payments"'::jsonb OR(j->>'createdAt')::numeric<(r->>'createdAt')::numeric;
  IF j->'feeBreakdownComplete' IS DISTINCT FROM to_jsonb(complete) OR j->'requiresFxReview' IS DISTINCT FROM to_jsonb(fx) OR j->'principalAmountMatched' IS DISTINCT FROM to_jsonb(matched) OR j->'sourceBinding' IS DISTINCT FROM to_jsonb(binding) OR j->'recognizedType' IS DISTINCT FROM to_jsonb(recognized) OR j->'requiresManualReview' IS DISTINCT FROM to_jsonb(manual) THEN RAISE EXCEPTION 'REFUND_RETURN_REVIEW_FLAGS_INVALID' USING ERRCODE='23514';END IF;
 ELSE
  IF j->>'state' IS DISTINCT FROM(CASE WHEN r->>'status' IS NULL OR r->>'status' NOT IN('failed','canceled') THEN 'not_returned' WHEN r->'failureBalanceTransactionId'='null'::jsonb THEN 'awaiting_return_balance' WHEN r->'failureBalanceTransactionId'=r->'balanceTransactionId' THEN 'source_conflict' ELSE 'return_balance' END) THEN RAISE EXCEPTION 'REFUND_RETURN_STATE_INVALID' USING ERRCODE='23514';END IF;
 END IF;
 IF NOT(j?&keys) OR j-keys<>'{}'::jsonb THEN RAISE EXCEPTION 'REFUND_RETURN_FIELDS_INVALID' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_academy::text||':checkout-provider:'||(draft->>'accountId'),0));
 SELECT * INTO existing FROM public.checkout_refund_return_inspections WHERE academy_id=p_academy AND id=p_id;IF FOUND THEN IF existing.start_id=p_start AND existing.refund_inspection_id=p_page AND existing.request_sha256=p_hash AND existing.return_inspection=j THEN RETURN CASE WHEN existing.object_conflict THEN 'duplicate_conflict' ELSE 'duplicate' END;END IF;RAISE EXCEPTION 'REFUND_RETURN_ID_CONFLICT' USING ERRCODE='23514';END IF;
 conflict=original.object_conflict OR j->>'state'='source_conflict' OR coalesce(binding='mismatch',false);
 IF j->>'state'='return_balance' THEN
  INSERT INTO public.checkout_balance_object_bindings(academy_id,account_id,livemode,transaction_id,start_id,charge_id) VALUES(p_academy,draft->>'accountId',(draft->>'livemode')::boolean,j->>'balanceTransactionId',p_start,j->>'chargeId') ON CONFLICT DO NOTHING;
  INSERT INTO public.checkout_refund_return_bindings(academy_id,account_id,livemode,transaction_id,start_id,refund_id,amount,currency) VALUES(p_academy,draft->>'accountId',(draft->>'livemode')::boolean,j->>'balanceTransactionId',p_start,r->>'id',(j->>'grossAmount')::numeric,j->>'currency') ON CONFLICT DO NOTHING;
  conflict=conflict OR NOT EXISTS(SELECT 1 FROM public.checkout_balance_object_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId' AND start_id=p_start AND charge_id=j->>'chargeId') OR NOT EXISTS(SELECT 1 FROM public.checkout_refund_return_bindings WHERE academy_id=p_academy AND account_id=draft->>'accountId' AND livemode=(draft->>'livemode')::boolean AND transaction_id=j->>'balanceTransactionId' AND start_id=p_start AND refund_id=r->>'id' AND amount=(j->>'grossAmount')::numeric AND currency=j->>'currency') OR EXISTS(SELECT 1 FROM public.checkout_fee_inspections fee JOIN public.checkout_balance_object_bindings owner ON owner.academy_id=fee.academy_id AND owner.start_id=fee.start_id AND owner.transaction_id=fee.fee_inspection->>'balanceTransactionId' WHERE fee.academy_id=p_academy AND owner.account_id=draft->>'accountId' AND owner.livemode=(draft->>'livemode')::boolean AND owner.transaction_id=j->>'balanceTransactionId');
 END IF;
 INSERT INTO public.checkout_refund_return_inspections(academy_id,id,start_id,refund_inspection_id,refund_id,worker_id,request_sha256,return_inspection,object_conflict) VALUES(p_academy,p_id,p_start,p_page,r->>'id',p_worker,p_hash,j,conflict);
 INSERT INTO public.checkout_refund_attention(academy_id,start_id,charge_id,inspection_id) VALUES(p_academy,p_start,j->>'chargeId',p_page) ON CONFLICT DO NOTHING;
 IF conflict THEN INSERT INTO public.checkout_refund_attention(academy_id,start_id,charge_id,inspection_id) SELECT p_academy,b.start_id,g.charge_id,p_page FROM public.checkout_refund_return_bindings b JOIN public.checkout_balance_object_bindings g ON g.academy_id=b.academy_id AND g.account_id=b.account_id AND g.livemode=b.livemode AND g.transaction_id=b.transaction_id WHERE b.academy_id=p_academy AND b.account_id=draft->>'accountId' AND b.livemode=(draft->>'livemode')::boolean AND b.transaction_id=j->>'balanceTransactionId' ON CONFLICT DO NOTHING;END IF;
 INSERT INTO public.outbox_events(academy_id,id,event_type,entity_id,request_id) VALUES(p_academy,gen_random_uuid(),CASE WHEN conflict THEN 'checkout.refund_return.object_conflict.critical' ELSE 'checkout.refund_return.observed.critical' END,p_start,p_id);
 RETURN CASE WHEN conflict THEN 'recorded_conflict' ELSE 'recorded' END;
END $$;
ALTER FUNCTION public.record_checkout_refund_return_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) OWNER TO kavosh_checkout_result_policy;REVOKE CREATE ON SCHEMA public FROM kavosh_checkout_result_policy;
REVOKE ALL ON FUNCTION public.record_checkout_refund_return_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_checkout_refund_return_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb) TO kavosh_checkout_result_worker;
-- Keep publication in the existing exact native checkout envelope/portal floor.
GRANT SELECT(academy_id,id,start_id,return_inspection,object_conflict,origin_transaction) ON public.checkout_refund_return_inspections TO kavosh_event_policy;
DO $$ DECLARE d text;needle text;changed text;BEGIN
 d=pg_get_functiondef('public.checkout_notice_basis(uuid,xid8)'::regprocedure);needle='IF o.event_type LIKE ''checkout.provider.%'' THEN';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_NOTICE_BASE_CHANGED';END IF;
 EXECUTE replace(d,needle,$branch$IF o.event_type LIKE 'checkout.refund_return.%' THEN
  SELECT id,return_inspection,object_conflict INTO r FROM public.checkout_refund_return_inspections WHERE academy_id=tenant AND start_id=s.id AND id=o.request_id AND origin_transaction=p_origin;
  IF r.id IS NULL THEN RETURN NULL;END IF;j=r.return_inspection;conflict=r.object_conflict;phase='refund_return';state=j->>'state';expected=CASE WHEN conflict THEN 'checkout.refund_return.object_conflict.critical' ELSE 'checkout.refund_return.observed.critical' END;key='refund_return:'||r.id::text;
 ELSIF o.event_type LIKE 'checkout.provider.%' THEN$branch$);
 d=pg_get_functiondef('public.checkout_notice_effect_required()'::regprocedure);needle='WHEN ''checkout_provider_inspections'' THEN';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_EFFECT_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'WHEN ''checkout_refund_return_inspections'' THEN key=''refund_return:''||NEW.id::text;'||E'\n '||needle);
 d=pg_get_functiondef('public.record_checkout_fee_inspection(uuid,uuid,uuid,uuid,uuid,text,jsonb)'::regprocedure);needle='conflict:=original.object_conflict;';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_FEE_BINDING_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'conflict:=original.object_conflict OR EXISTS(SELECT 1 FROM public.checkout_refund_return_bindings WHERE academy_id=p_academy AND account_id=draft->>''accountId'' AND livemode=(draft->>''livemode'')::boolean AND transaction_id=j->>''balanceTransactionId'');');
 d=pg_get_functiondef('public.provider_credit_review_basis(uuid,uuid[])'::regprocedure);needle='OR EXISTS(SELECT 1 FROM public.checkout_refund_inspections bad';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_REVIEW_CONFLICT_BASE_CHANGED';END IF;
 changed=replace(d,needle,'OR EXISTS(SELECT 1 FROM public.checkout_refund_return_inspections bad WHERE bad.academy_id=c.academy_id AND bad.object_conflict AND(bad.start_id=c.start_id OR EXISTS(SELECT 1 FROM public.checkout_refund_return_bindings bound WHERE bound.academy_id=c.academy_id AND bound.account_id=c.account_id AND bound.livemode=c.livemode AND bound.start_id=c.start_id AND bound.transaction_id=bad.return_inspection->>''balanceTransactionId''))) '||needle);
 needle='),transitions AS(SELECT *,lag(fact)';IF strpos(changed,needle)=0 THEN RAISE EXCEPTION 'REFUND_RETURN_REVIEW_HISTORY_BASE_CHANGED';END IF;EXECUTE replace(changed,needle,' UNION ALL SELECT ''return:''||i.refund_id,i.received_at,i.id,jsonb_build_object(''conflict'',i.object_conflict,''fact'',i.return_inspection) FROM public.checkout_refund_return_inspections i WHERE i.academy_id=c.academy_id AND i.start_id=c.start_id '||needle);
END $$;
DROP TRIGGER checkout_notice_capture ON public.outbox_events;
CREATE TRIGGER checkout_notice_capture AFTER INSERT ON public.outbox_events FOR EACH ROW WHEN(NEW.event_type IN('checkout.transport.received','checkout.transport.actor_conflict.critical','checkout.transport.conflict.critical','checkout.provider.object_conflict.critical','checkout.provider.review.critical','checkout.provider.observed','checkout.fees.object_conflict.critical','checkout.fees.observed','checkout.refunds.review_required.critical','checkout.refunds.observed','checkout.refund_return.observed.critical','checkout.refund_return.object_conflict.critical')) EXECUTE FUNCTION public.capture_checkout_notice();
CREATE CONSTRAINT TRIGGER checkout_notice_effect AFTER INSERT ON public.checkout_refund_return_inspections DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.checkout_notice_effect_required();
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 307 $$;
